// Seeded "how to perform" text for every library exercise, shown by the
// Info button during a workout.
//
// Seeded rather than AI-generated on demand: the lazy path cached whatever
// came back, so a missing API key or a failed call would permanently store
// generic filler on the exercise row. Custom user-created exercises still
// fall back to generation (src/lib/ai/alex.ts).

export const EXERCISE_INSTRUCTIONS: Record<string, string> = {
  "45-Degree Back Extension":
    "1. Set the pad just below your hip bones so your hips can bend freely.\n\n2. Cross your arms over your chest, brace your core, and hinge forward from the hips with a flat back.\n\n3. Lower until you feel a good stretch through the hamstrings and glutes.\n\n4. Squeeze your glutes to lift back up until your body forms one straight line, and no higher. Start with bodyweight only before holding a plate. Key cue: finish each rep with a glute squeeze, not a back arch. Common mistake: hyperextending at the top, which loads the lower back instead of the glutes.",
  "Ab Wheel Rollout":
    "1. Kneel on a pad with the wheel under your shoulders, arms straight, glutes squeezed and ribs tucked down.\n\n2. Roll out slowly only as far as you can go without your lower back arching, then pull your hips back with your abs to return.\n\n3. Start with a short range and add a few inches as you get stronger.\n\n4. Key cue: keep the pelvis tucked under for the whole rep. Your abs are resisting extension, not dragging you back with your arms.\n\n5. Common mistake: rolling out until the lower back sags into an arch. That is exactly where back strains happen, so stop short of it.",
  "Adductor Machine":
    "1. Sit tall with your back against the pad and the insides of your thighs on the pads.\n\n2. Start with your legs open only as far as feels like a comfortable stretch, never forced.\n\n3. Squeeze your knees together smoothly, pause for a beat with the pads nearly touching, then open slowly against the resistance.\n\n4. Key cue: keep your glutes and back flat on the seat so your inner thighs do all the work. Common mistake: setting the starting width too wide, which strains the groin in the most vulnerable part of the range.",
  "Arnold Press":
    "1. Sit on an upright bench holding dumbbells in front of your chest, palms facing you and elbows tucked in.\n\n2. As you press up, rotate your palms outward so they face forward at the top.\n\n3. Finish with the dumbbells over your shoulders, elbows nearly straight and ribs pulled down.\n\n4. Reverse the exact path, rotating back to palms-facing-you as the dumbbells reach chest height.\n\nKey cue: rotate smoothly through the whole press instead of twisting at the last second. Common mistake: going too heavy, which turns the rotation into a shrug and grinds the shoulder joint.",
  "Assisted Dip":
    "1. Set the assist weight so you can finish your target reps with two or three left in the tank.\n\n2. Grip the handles, step or kneel onto the pad, and press up to straight arms with your shoulders pulled down.\n\n3. Keep your torso close to upright so the emphasis stays on your triceps.\n\n4. Lower until your elbows reach about 90 degrees, then press back up without slamming into lockout.\n\nKey cue: more weight on the assist pad means more help, so the numbers work backwards. Common mistake: sinking too deep and letting your shoulders shrug up around your ears.",
  "Assisted Pull-Up":
    "1. Set the assist weight so you finish your target reps with two or three left in the tank. More assist weight makes the rep easier.\n\n2. Kneel or stand on the pad, grip just outside shoulder width, and let your arms straighten fully.\n\n3. Pull your shoulder blades down first, then drive your elbows down until your chin clears the bar.\n\n4. Key cue: keep ribs down and glutes squeezed so you travel straight up instead of arching your back.\n\n5. Common mistake: dropping fast and letting the pad spring you back up. Pause for a beat at a full hang and start each rep from a dead stop.",
  "B-Stance Hip Thrust":
    "1. Sit with your upper back on a bench and a padded dumbbell across your hip crease, knees bent and feet flat.\n\n2. Slide one foot forward so only its heel rests on the floor. The working leg stays flat and takes most of the load.\n\n3. Drive through the working heel to lift your hips into a straight line from knees to shoulders.\n\n4. Squeeze for a beat, lower under control, finish all reps, then switch legs. You are loading one leg, so use far less weight than a two-leg hip thrust. Key cue: the kickstand leg is for balance only. Common mistake: pushing evenly with both legs, which just makes it a regular hip thrust.",
  "Band Bent-Over Row":
    "1. Stand on the middle of a resistance band, feet hip-width, holding one end in each hand.\n\n2. Hinge at the hips until your torso is about 45 degrees, back flat and knees soft.\n\n3. Row your hands to your lower ribs, pulling your elbows back and squeezing your shoulder blades.\n\n4. Straighten your arms slowly against the band's pull.\n\nCue: keep tension on the band at the bottom instead of letting it go slack. Common mistake: rounding the low back as you tire - stand slightly taller rather than losing the flat back.",
  "Band Chest Fly":
    "1. Anchor a band at chest height behind you and hold one end in each hand.\n\n2. Step forward into a split stance with your arms out to the sides and a slight bend in the elbows.\n\n3. Sweep your hands forward and together in a wide arc until they meet in front of your chest.\n\n4. Squeeze for a beat, then let your arms open slowly against the band's pull.\n\nKey cue: keep the elbow angle fixed so this stays a fly and not a press. Common mistake: letting your hands drift up toward your face, which turns it into a front raise for the delts.",
  "Band Chest Press":
    "1. Anchor a resistance band at chest height behind you, or loop it across your upper back and under your arms.\n\n2. Hold an end in each hand at chest level with your elbows bent and palms facing down.\n\n3. Step forward into a split stance so the band is already under tension before your first rep.\n\n4. Press both hands forward and slightly together until your arms are straight, then return slowly until you feel a stretch.\n\nKey cue: keep your ribs down so you press with your chest, not your low back. Common mistake: letting the band snap your hands back, since the return half is where much of the growth happens.",
  "Band Curl":
    "1. Stand on the middle of the band with feet about hip width and hold an end in each hand, palms up.\n\n2. Curl your hands toward your shoulders with elbows pinned to your sides until the biceps are fully contracted.\n\n3. Lower slowly and fight the band on the way down instead of letting it snap your arms straight.\n\n4. Key cue: bands get harder the further they stretch, so squeeze extra hard at the top where resistance peaks.\n\n5. Common mistake: widening your stance mid-set to shorten the band and make it easier. Pick a band you can control for all your reps.",
  "Band Lat Pulldown":
    "1. Anchor a resistance band overhead on a door anchor or a sturdy beam.\n\n2. Kneel or sit far enough back that the band is already tense with your arms straight overhead.\n\n3. Pull your shoulder blades down, then drive your elbows down and back until your hands reach chest level.\n\n4. Return slowly and let your arms fully straighten each rep.\n\nCue: squeeze for a second at the bottom where the band tension is highest. Common mistake: leaning back to create tension - move farther from the anchor or use a heavier band instead.",
  "Band Low-to-High Chop":
    "1. Anchor a band near the floor and stand side-on, holding it with both hands by your outside hip.\n\n2. Set your feet shoulder-width apart and step out until the band has tension.\n\n3. Brace your abs and pull the band diagonally up and across toward the opposite shoulder.\n\n4. Pivot the back foot as you rotate, then return slowly along the same path. Finish all reps before switching sides.\n\nKey cue: finish with your chest facing the direction of the chop. Common mistake: leaning back at the top - stay tall and rotate instead.",
  "Band Overhead Press":
    "1. Stand on the middle of a resistance band with feet hip width apart and an end in each hand.\n\n2. Bring your hands to shoulder height, palms facing forward and elbows under your wrists.\n\n3. Brace your abs and squeeze your glutes so your ribs stay stacked over your hips.\n\n4. Press straight overhead until your arms lock out with your biceps near your ears, then lower slowly.\n\nKey cue: step wider on the band to add resistance. Common mistake: arching the low back to finish the rep instead of pressing in a straight line.",
  "Band Pull-Apart":
    "1. Hold a light band with both hands, arms straight out in front at chest height, palms down.\n\n2. Set your shoulders down and back and brace your core.\n\n3. Pull the band apart until your arms are out to your sides, squeezing your shoulder blades together.\n\n4. Return slowly to the start under control.\n\nCue: keep your arms straight and lead with the outside of your hands. Common mistake: shrugging toward your ears - keep the shoulders pinned down so the rear delts and mid-back do the work.",
  "Band Triceps Pushdown":
    "1. Anchor a resistance band overhead on a door anchor, squat rack, or sturdy bar.\n\n2. Hold an end in each hand and step back until there is tension, elbows pinned at your sides.\n\n3. Stand tall with a slight forward lean and your abs braced.\n\n4. Extend your elbows until your arms are straight, then let the band pull your hands back up slowly to about 90 degrees.\n\nKey cue: keep your elbows glued to your ribs for every rep. Common mistake: leaning your whole bodyweight into the band to force reps out, which turns it into a chest and lat movement.",
  "Band-Assisted Pull-Up":
    "1. Loop a resistance band over the bar and pull the bottom of the loop through itself.\n\n2. Put one knee or foot in the band, grip the bar just outside shoulder width, and hang with arms straight.\n\n3. Pull your shoulder blades down, then drive your elbows down until your chin clears the bar.\n\n4. Lower under control to a full hang, and move to a thinner band as you get stronger.\n\nCue: keep your chest tall and think elbows to ribs. Common mistake: letting the band bounce you up - stay tight so you control the bottom instead of springing out of it.",
  "Banded Glute Bridge":
    "1. Loop a mini band just above your knees and lie on your back with knees bent, feet flat and hip-width.\n\n2. Press your knees outward against the band so it stays under tension before you move.\n\n3. Drive through your heels and lift your hips until your body forms a straight line from knees to shoulders.\n\n4. Squeeze the glutes hard at the top, then lower until your hips almost touch the floor. Key cue: keep pushing the band apart for the whole set. Common mistake: letting your knees collapse inward, which hands the work over to your quads.",
  "Banded Glute Kickback":
    "1. Anchor a band low in front of you and loop the free end around one ankle.\n\n2. Stand tall facing the anchor, far enough back that the band is tight, with a hand on a wall or rack for balance.\n\n3. Shift your weight onto the free leg, brace your core, and square your hips so your lower back stays flat.\n\n4. Drive the working leg straight back, squeeze the glute, then return slowly against the band. Finish your reps, then switch sides. Key cue: think hip extension, not leg height. Common mistake: arching the lower back to lift higher, which moves the work from your glute to your spine.",
  "Banded Hamstring Curl":
    "1. Anchor a band low to the floor and loop the free end around one ankle.\n\n2. Lie face down with your feet pointing toward the anchor, far enough away that the band is already tight with your leg straight.\n\n3. Keeping your hip bones pressed into the floor, curl your heel toward your glute against the band.\n\n4. Squeeze at the top, lower slowly, and finish all reps before switching legs. Key cue: only the lower leg moves. Common mistake: lifting the knee off the floor and arching your lower back to squeeze out more range.",
  "Banded Lateral Walk":
    "1. Loop a mini band just above your knees, or around your ankles for a harder version.\n\n2. Sit into a quarter squat with your chest up and push your knees out to keep tension on the band.\n\n3. Step sideways with the lead foot, then follow with a controlled step from the trail foot, never letting your feet touch.\n\n4. Take 10 to 15 steps one way, then walk it back the other way.\n\n5. Key cue: stay low and keep your hips level the whole set. Common mistake: standing upright and letting your knees cave in, which drops all the tension off your glutes.",
  "Banded Standing Adduction":
    "1. Anchor a band at ankle height and loop it around the ankle nearest the anchor.\n\n2. Stand side-on and step away until the band is tight, holding something for balance.\n\n3. Keeping the working leg straight, pull it across your body in front of the standing leg against the band.\n\n4. Squeeze the inner thigh, then let the band draw the leg back out slowly and repeat before switching sides. Key cue: stay tall and move only at the hip. Common mistake: swinging the leg and letting the band snap it back instead of controlling the return.",
  "Banded Standing Crunch":
    "1. Anchor a band high, face away from it, and hold the ends beside your head.\n\n2. Stand with feet hip-width, knees soft, and step forward until the band is tight.\n\n3. Brace your abs and crunch your ribs toward your hips, rounding your upper back.\n\n4. Rise slowly back to standing while resisting the band's pull.\n\nKey cue: keep your hips still so the movement happens in your torso, not your legs. Common mistake: bending at the hips like a bow - think about closing the space between ribcage and belt.",
  "Barbell Bench Press":
    "1. Lie back with your eyes under the bar, feet flat, and squeeze your shoulder blades down and together into the bench.\n\n2. Unrack and lower the bar to mid-chest with your elbows tucked to about 45 degrees from your torso.\n\n3. Touch the chest lightly, then press up and slightly back so the bar finishes over your shoulders with straight arms.\n\n4. Key cue: keep those shoulder blades pinned for the whole set so your chest does the work instead of your shoulders.\n\n5. Common mistake: flaring the elbows straight out to the sides, which grinds the shoulder joint. Keep them tucked.",
  "Barbell Curl":
    "1. Stand tall holding the bar at shoulder width, palms up, arms straight, elbows tucked at your sides.\n\n2. Curl the bar up by bending only at the elbow until your forearms pass vertical.\n\n3. Lower slowly over two to three seconds until your arms are completely straight.\n\n4. Key cue: keep your elbows pinned to your ribs. If they drift forward, your front delts are taking over the lift.\n\n5. Common mistake: swinging the hips and leaning back to launch the bar. Drop the weight if your torso moves, and use an EZ bar if a straight bar bothers your wrists.",
  "Barbell Hip Thrust":
    "1. Sit on the floor with your upper back against a bench and roll a padded barbell over your hips.\n\n2. Plant your feet flat, about hip-width, close enough that your shins finish vertical at the top.\n\n3. Tuck your chin, brace your core, and drive through your heels until your torso is parallel to the floor, squeezing your glutes hard.\n\n4. Lower under control until the plates just kiss the floor, then go again.\n\n5. Key cue: finish each rep with your ribs down and pelvis slightly tucked. Common mistake: overextending your lower back at the top to fake extra height.",
  "Barbell Row":
    "1. Hinge at the hips until your torso is about 45 degrees or lower, knees soft, bar hanging under your shoulders with an overhand grip.\n\n2. Brace your abs hard and set your back flat. That position holds for every rep.\n\n3. Row the bar to your lower ribs, elbows tracking back at roughly 45 degrees, then lower under control.\n\n4. Key cue: pull with your elbows and keep the bar traveling close to your body instead of swinging out away from you.\n\n5. Common mistake: standing up as you row so your torso angle rises rep by rep. Lighten the load and keep the hinge locked in.",
  "Barbell Shrug":
    "1. Set a barbell in a rack at hip height or deadlift it up, gripping just outside your thighs.\n\n2. Stand tall with the bar against your legs, arms straight and chest up.\n\n3. Shrug your shoulders straight up toward your ears as high as they will go.\n\n4. Hold for a beat at the top, then lower slowly until you feel your traps stretch.\n\nCue: straight up and down, arms acting only as hooks. Common mistake: rolling the shoulders backward at the top - it adds no trap work and grinds the shoulder joint.",
  "Barbell Squat":
    "1. Set the bar on your upper traps, unrack it, and step back into a stance about shoulder-width with your toes turned out slightly.\n\n2. Take a big breath, brace your core hard, and sit down between your hips with your knees tracking over your middle toes.\n\n3. Descend to at least parallel, going only as deep as you can keep your lower back flat, then drive through your whole foot to stand tall and squeeze your glutes.\n\n4. Key cue: keep your chest proud and your elbows under the bar so your torso stays supported. Common mistake: letting your hips shoot up first out of the hole, which turns the squat into a good morning and dumps the load on your lower back.",
  "Battle Ropes":
    "1. Anchor the ropes, take one end in each hand, and step back until there is only slight slack.\n\n2. Sit into a quarter squat with soft knees, chest up, and a flat back.\n\n3. Make fast alternating waves from the shoulders, sending each wave all the way down to the anchor.\n\n4. Go hard for 20 to 30 seconds, rest 40 to 60 seconds, and repeat for 8 to 12 rounds.\n\nKey cue: brace your trunk so the arms move while the torso stays still. Common mistake: standing straight-legged and flailing from the elbows, which fries the shoulders and kills the wave.",
  "Bench Dip":
    "1. Sit on the edge of a bench with your hands next to your hips, fingers pointing forward, then slide your hips off the front.\n\n2. Keep your knees bent and heels close for an easier version, or walk the feet out straight for more load.\n\n3. Bend your elbows straight back and lower until your upper arms are about parallel to the floor, then press back up.\n\n4. Key cue: keep your hips brushing close to the bench and your chest tall so the shoulders stay in a safe position.\n\n5. Common mistake: sinking too deep, which jams the front of the shoulder. Stop at parallel.",
  "Bicycle Crunch":
    "1. Lie on your back with hands resting lightly behind your head and knees bent to 90 degrees.\n\n2. Curl your shoulder blades off the floor and press your low back down.\n\n3. Extend one leg while rotating your opposite shoulder toward the bent knee.\n\n4. Switch sides smoothly and keep alternating. One turn to each side is one rep.\n\nKey cue: bring the shoulder toward the knee, not the elbow - the rotation comes from your ribs. Common mistake: yanking on your neck and speeding up; keep your hands loose and move slowly.",
  "Bird Dog":
    "1. Set up on hands and knees with hands under shoulders, knees under hips, and a flat back.\n\n2. Brace your abs and reach your right arm forward while extending your left leg straight back.\n\n3. Pause for two seconds with your body in one long line from fingertips to heel.\n\n4. Lower under control and switch sides. That is one rep.\n\nKey cue: imagine balancing a glass of water on your low back so your hips stay square. Common mistake: kicking the leg up high and arching the back - keep the foot no higher than hip height. If your wrists complain, drop to your forearms or make fists.",
  "Bodyweight Squat":
    "1. Stand shoulder-width with your toes turned out slightly and your arms reaching forward as a counterbalance.\n\n2. Push your hips back and bend your knees at the same time, lowering until your thighs are at least parallel to the floor.\n\n3. Keep your heels planted and your chest up, then drive through your feet to stand and squeeze your glutes.\n\n4. Key cue: control the descent for two full counts instead of dropping into the bottom. Common mistake: letting the knees collapse inward on the way up, so think about spreading the floor apart with your feet.",
  "Box Step-Over":
    "1. Set a box or bench around knee height and stand close enough to step on without reaching for it.\n\n2. Plant your whole foot on the box, drive through the heel, and stand up tall on top.\n\n3. Step down under control on the far side, turn around, and repeat leading with the other leg.\n\n4. Keep a steady rhythm for 12 to 20 step-overs, rest 60 seconds, and repeat for 4 to 6 rounds.\n\nKey cue: the working knee tracks over the middle toes. Common mistake: bouncing off the trailing foot to hop up, which cheats the leg that is supposed to be doing the work.",
  "Bulgarian Split Squat":
    "1. Stand about two feet in front of a bench and rest the top of your rear foot on it, laces down.\n\n2. With dumbbells at your sides, hinge your torso forward a few degrees and lower straight down until your back knee nearly touches the floor.\n\n3. Drive through your front heel to stand back up, keeping both hip bones square to the front.\n\n4. Key cue: nearly all your weight belongs on the front leg, the back foot is only a kickstand. Common mistake: setting up too close to the bench, which jams the front knee and kills the glute stretch.",
  "Cable Adduction":
    "1. Cuff the ankle closest to the machine and stand side-on, far enough away that the working leg starts out to the side.\n\n2. Hold the frame for balance, stand tall, and brace your core.\n\n3. Pull the working leg across your body, past the standing leg, and squeeze your inner thigh at the end.\n\n4. Let the cable draw your leg back out slowly until you feel a comfortable stretch.\n\n5. Key cue: keep your hips level and your torso quiet. Common mistake: swinging the leg with momentum and leaning your body to drag the weight across.",
  "Cable Crunch":
    "1. Attach a rope high on the cable, kneel facing the stack, and hold the rope at the sides of your head.\n\n2. Keep your hips still, then crunch by rounding your spine and pulling your ribs down toward your pelvis.\n\n3. Come up slowly, letting the weight stretch your abs without your hips traveling backward.\n\n4. Key cue: this is spinal flexion, not a hip hinge. Your hips stay in one spot while your chest curls under.\n\n5. Common mistake: sitting back and pulling with straight arms so the lats do the work. Lock your elbow angle and let the abs move the weight.",
  "Cable Curl":
    "1. Set the pulley at its lowest position and attach an EZ bar or rope, both of which are kinder on the wrists than a straight bar.\n\n2. Step back far enough that the cable is under tension with your arms straight, then stand tall with elbows at your sides.\n\n3. Curl up until your forearms pass vertical, then lower slowly and resist the cable back to straight arms without letting your elbows drift forward.\n\n4. Key cue: cables keep tension on the biceps at every angle, so pause a beat at the top and feel the squeeze.\n\n5. Common mistake: standing too close to the stack, which kills the tension through the bottom half of the rep.",
  "Cable Fly":
    "1. Set both pulleys to about chest height, take a handle in each hand, and stand in the middle in a split stance.\n\n2. Start with your arms wide and elbows softly bent, chest tall, shoulder blades set down and back.\n\n3. Sweep your hands together in front of your chest in a hugging arc and squeeze for a beat.\n\n4. Key cue: lock that slight elbow bend and hold it. The angle should not change on the way in or out.\n\n5. Common mistake: bending and straightening the elbows, which quietly turns your fly into a press.",
  "Cable Glute Kickback":
    "1. Strap the ankle cuff on one ankle, face the low pulley, and hold the frame for balance.\n\n2. Hinge your torso forward slightly, brace your core, and set a soft bend in the working knee.\n\n3. Drive the working leg back and slightly up until your hip is fully extended, then squeeze the glute for a beat.\n\n4. Return slowly against the cable instead of letting it snap your leg forward.\n\n5. Key cue: keep your hips square and your ribs down. Common mistake: arching your lower back to gain range, which turns a glute exercise into a spine exercise.",
  "Cable Lateral Raise":
    "1. Set a single pulley to its lowest setting and stand side-on, taking the handle with the hand farthest from the stack, across your body.\n\n2. Stand tall, brace your core, and keep a soft, fixed bend in the working elbow.\n\n3. Raise your arm out to the side until it reaches shoulder height, then lower slowly against the cable's pull.\n\n4. Key cue: the cable keeps tension even at the bottom, so stay smooth and resist the urge to rest between reps.\n\n5. Common mistake: leaning away from the stack to cheat the weight up. Keep your torso still.",
  "Cable Overhead Triceps Extension":
    "1. Set a cable pulley to the lowest setting, attach a rope, and grab it with both hands.\n\n2. Turn away from the stack and bring the rope behind your head with your elbows pointing up and forward.\n\n3. Step into a split stance and brace your abs so your ribs stay down.\n\n4. Extend your elbows until your arms are straight overhead, spreading the rope apart at the top.\n\n5. Lower slowly until you feel a stretch along the back of your arms.\n\nKey cue: only your elbows move, upper arms stay put. Common mistake: letting the elbows flare and drift down, which turns it into a shoulder exercise.",
  "Cable Pull-Through":
    "1. Face away from a low pulley with a rope attachment passed between your legs and an end in each hand.\n\n2. Walk out until there is tension, set a hip-width stance, and put a soft bend in your knees.\n\n3. Push your hips back and let the rope pull your hands between your legs until you feel a hamstring stretch.\n\n4. Drive your hips forward to stand tall and squeeze your glutes, keeping your arms relaxed and your spine long.\n\n5. Key cue: your arms are only hooks, your hips do all the work. Common mistake: turning it into a squat or a cable row instead of a pure hinge.",
  "Cable Woodchop":
    "1. Set the cable high and stand side-on, feet shoulder-width, gripping the handle with both hands.\n\n2. Brace your abs and pull the handle down and across your body toward the opposite hip.\n\n3. Let your back foot pivot as your ribcage rotates, keeping your arms nearly straight.\n\n4. Return to the top slowly, resisting the cable, then finish all reps before switching sides.\n\nKey cue: rotate through your ribcage and hips together, not with your arms alone. Common mistake: yanking with the shoulders while the torso stays still.",
  "Captain's Chair Knee Raise":
    "1. Step into the captain's chair with your forearms on the pads and hands on the handles.\n\n2. Press your shoulders down away from your ears and flatten your low back against the pad.\n\n3. Brace your abs and lift your knees toward your chest, curling your pelvis up slightly at the top.\n\n4. Lower slowly until your legs hang straight, keeping tension the whole way.\n\nKey cue: the rep really starts when your pelvis tilts - anything before that is hip flexors. Common mistake: swinging the legs up and dropping them.",
  "Chest Dip":
    "1. Grip parallel bars and press up to a locked-out start with your legs crossed behind you.\n\n2. Lean your torso forward about 30 degrees and let your elbows flare slightly out to the sides.\n\n3. Lower under control until your shoulders are roughly level with your elbows and you feel a stretch across the chest.\n\n4. Press back up by squeezing the chest, stopping just short of a hard lockout.\n\nKey cue: hold the forward lean the whole way, or the work shifts to your triceps. Common mistake: dropping too deep and letting the shoulders roll forward, which is where most dip injuries come from.",
  "Chest-Supported Row":
    "1. Set the chest pad so the handles sit around mid-chest height and plant your feet firmly.\n\n2. Lie into the pad, take the handles at arms length, and let your shoulder blades spread at the start of each rep.\n\n3. Row the handles toward your lower ribs, squeezing your shoulder blades together, then lower slowly.\n\n4. Key cue: with your chest supported there is no reason to cheat, so keep it glued to the pad the entire set.\n\n5. Common mistake: peeling off the pad to move heavier weight. That turns it into a barbell row and undoes the low-back-friendly benefit.",
  "Chin-Up":
    "1. Grab the bar with an underhand grip, hands about shoulder-width apart, and hang with your arms straight.\n\n2. Pull your shoulder blades down and back first, then drive your elbows toward your ribs until your chin clears the bar.\n\n3. Lower under control all the way back to straight arms before the next rep.\n\nCue: think about pulling your elbows into your back pockets rather than just bending your arms. Common mistake: kipping or swinging the legs to get up - keep your ribs down and your body quiet so your lats and biceps do the work.",
  "Clamshell":
    "1. Lie on your side with a mini band above your knees, hips and knees bent about 45 degrees, feet stacked.\n\n2. Stack your shoulders and hips vertically and rest your head on your bottom arm.\n\n3. Keeping your feet touching, rotate your top knee up against the band as far as you can without rolling backward.\n\n4. Pause at the top, then lower slowly. Key cue: keep your top hip stacked directly over the bottom one. Common mistake: rocking the pelvis backward to gain range, which shifts the work off the glute medius.",
  "Close-Grip Bench Press":
    "1. Lie on a flat bench and grip the bar at about shoulder width, roughly a thumb's length inside your normal bench grip.\n\n2. Unrack and lower the bar to your lower chest with your elbows tucked close to your ribs.\n\n3. Touch lightly, then press back up by driving through the triceps until your elbows straighten.\n\n4. Keep your wrists stacked over your forearms and your shoulder blades pinned back the whole set.\n\nKey cue: elbows in, forearms vertical. Common mistake: gripping too narrow, which torques the wrists and elbows without adding any extra triceps work.",
  "Close-Grip Lat Pulldown":
    "1. Attach a close neutral or V handle, set the thigh pad snug, and sit tall.\n\n2. Grip the handle, lean back about 10 to 15 degrees, and lift your chest.\n\n3. Pull the handle to your upper chest by driving your elbows down and back.\n\n4. Return under control until your arms are straight and you feel a stretch through your lats.\n\nCue: lead with your elbows, not your hands, and pause for a beat at your chest. Common mistake: rocking the torso back to heave the weight down - keep the same lean angle from the first rep to the last.",
  "Concentration Curl":
    "1. Sit on a bench with your feet wide and hold a dumbbell in one hand.\n\n2. Brace the back of your upper arm against the inside of your thigh with the arm hanging straight down.\n\n3. Curl the dumbbell toward your opposite shoulder, turning your pinky slightly inward at the top.\n\n4. Lower all the way until your arm is straight, finish your reps, then switch sides.\n\nCue: squeeze hard for a full second at the top - this is a feel exercise, not a heavy one. Common mistake: pushing your leg into your arm to help lift the weight.",
  "Conventional Deadlift":
    "1. Set your feet hip-width under the bar so it sits over your mid-foot, then grip just outside your shins.\n\n2. Drop your hips until your shins touch the bar, lift your chest, and pull the slack out of the bar so your lats engage.\n\n3. Push the floor away and stand up, keeping the bar traveling in a straight line up your legs.\n\n4. Lock out by squeezing your glutes, then hinge the bar back down under control.\n\n5. Key cue: brace before every single rep like you are about to be punched. Common mistake: letting your hips rise before the bar leaves the floor, which rounds your back and stalls the lift.",
  "Copenhagen Plank":
    "1. Lie on your side with your top leg resting on a bench and your elbow under your shoulder.\n\n2. Squeeze the top leg down into the bench and lift your hips until your body is one straight line.\n\n3. Let the bottom leg hover, or rest it under the bench for support.\n\n4. Hold 15 to 20 seconds per side - that is one rep - then lower with control.\n\nKey cue: drive through the inner thigh of the top leg, not just the shoulder. Common mistake: starting at full length - support at the knee first and build up to the ankle.",
  "Cossack Squat":
    "1. Stand with your feet much wider than shoulder-width, toes slightly turned out.\n\n2. Shift your weight onto one leg and sit down into that hip, keeping the other leg straight with its toes pointed up.\n\n3. Go as low as you can with your heel down and chest up, feeling a stretch in the straight leg's inner thigh.\n\n4. Push back to center and repeat on the other side. Key cue: keep both heels on the floor. Common mistake: forcing depth before your hips are ready, which rounds the lower back and rolls the bent-side foot inward.",
  "Curtsy Lunge":
    "1. Stand with dumbbells at your sides, feet hip-width apart.\n\n2. Step one foot back and across behind the other, like a curtsy, keeping your hips square to the front.\n\n3. Lower until the front thigh is near parallel, front knee tracking over the middle of the foot.\n\n4. Drive through the front heel to return to standing, then repeat. Key cue: cross the leg behind you, not out to the side, with hips staying square. Common mistake: twisting the pelvis to reach further, which turns it into a normal lunge and irritates the front knee.",
  "Dead Bug":
    "1. Lie on your back with arms straight up over your shoulders and hips and knees bent to 90 degrees.\n\n2. Press your lower back flat into the floor and hold it there for the whole set.\n\n3. Slowly lower your right arm overhead and straighten your left leg toward the floor, exhaling as you go.\n\n4. Return to the start under control and repeat on the other side. That is one rep.\n\nKey cue: keep your ribs pulled down so your back never arches off the floor. Common mistake: rushing and letting the low back pop up as the leg extends - shorten the range instead.",
  "Decline Barbell Bench Press":
    "1. Hook your legs into the decline bench pads and lie back so the bar sits over your lower chest.\n\n2. Grip slightly wider than shoulder width, unrack with a spotter's help if you have one, and take a breath.\n\n3. Lower the bar to the bottom edge of your chest with your elbows tucked to about 45 degrees.\n\n4. Press straight up over the same spot and lock out without letting your hips peel off the bench.\n\nKey cue: pin your shoulder blades together and hold that position throughout. Common mistake: sitting up fast at the end of the set, which can leave you lightheaded. Rack the bar first, then come up slowly.",
  "Decline Push-Up":
    "1. Set your feet on a bench or box and place your hands slightly wider than shoulder width on the floor.\n\n2. Brace your abs and squeeze your glutes so your body is one straight line from heels to head.\n\n3. Lower your chest toward the floor with your elbows at about 45 degrees from your ribs.\n\n4. Press back to straight arms without letting your hips pike up or sag down.\n\nKey cue: the higher your feet, the more your upper chest and shoulders work. Common mistake: going so high that it becomes a shoulder press with a rounded low back. Start with your feet 12 to 18 inches up.",
  "Deficit Deadlift":
    "1. Stand on a one to two inch platform with the bar over your mid-foot, feet hip-width.\n\n2. Hinge down and grip just outside your knees, with hips slightly lower than a normal pull because of the extra range.\n\n3. Brace hard, pull the slack out of the bar, and drive the floor away with a flat back.\n\n4. Lock out, then lower under control back to the platform. Use noticeably less weight than your floor deadlift. Key cue: keep the bar dragging up your shins. Common mistake: chasing your usual deadlift load and rounding your back to reach the bar.",
  "Diamond Push-Up":
    "1. Set up in a push-up position with your hands together under your chest, index fingers and thumbs forming a triangle.\n\n2. Brace your abs and squeeze your glutes so your body is one straight line from heels to head.\n\n3. Lower your chest toward your hands with your elbows brushing close to your ribs.\n\n4. Press back to straight arms and squeeze the backs of your arms hard at the top.\n\nKey cue: elbows stay tucked, never flared out to the sides. Common mistake: letting the hips sag or the head crane forward to fake depth. Drop to your knees if you cannot hold the line.",
  "Dumbbell Bench Press":
    "1. Sit on the bench with the dumbbells on your thighs, then kick them up as you lie back and set your shoulder blades down and together.\n\n2. Start with the dumbbells just outside your chest, palms facing forward, elbows about 45 degrees from your ribs.\n\n3. Press up and slightly inward until the weights are over your chest, without clanging them together.\n\n4. Key cue: lower until you feel a stretch across your chest, roughly level with your torso, then drive back up.\n\n5. Common mistake: dropping the elbows far below the bench chasing depth, which strains the shoulder capsule.",
  "Dumbbell Curl":
    "1. Stand tall with a dumbbell in each hand, arms straight and palms facing forward.\n\n2. Curl one or both dumbbells up by bending at the elbow only, finishing with a hard biceps squeeze.\n\n3. Lower under control all the way to straight arms before the next rep.\n\n4. Key cue: keep your wrists straight rather than bent back, elbows pinned at your sides, and squeeze the biceps at the top of every rep.\n\n5. Common mistake: shrugging and rocking to move heavier bells. Half the growth happens on the way down, so control the lowering.",
  "Dumbbell Floor Press":
    "1. Sit on the floor with a dumbbell in each hand, then lie back with your knees bent and feet flat.\n\n2. Start with the dumbbells at chest height, palms facing forward, elbows about 45 degrees from your ribs.\n\n3. Lower until the backs of your upper arms lightly touch the floor, pause for a beat, then press up.\n\n4. Keep that pause honest so every rep starts from a dead stop instead of a bounce.\n\nKey cue: the floor limits your range on purpose, so let it protect your shoulders. Common mistake: slamming the elbows down, which stings and kills the tension you built.",
  "Dumbbell Pullover":
    "1. Lie on a flat bench with your feet planted, holding one dumbbell with both hands, palms flat on the top plate.\n\n2. Press it over your chest with a slight bend in your elbows.\n\n3. Lower the dumbbell back over your head until you feel a stretch across your lats and ribs.\n\n4. Pull it back over your chest along the same arc.\n\nCue: keep your ribs down and your low back on the bench so the stretch happens at the shoulders, not the spine. Common mistake: diving too deep too fast - stop where the stretch is strong but comfortable.",
  "Dumbbell Romanian Deadlift":
    "1. Hold a dumbbell in each hand in front of your thighs, feet hip-width, knees softly bent.\n\n2. Push your hips back and let the dumbbells travel down close to your legs.\n\n3. Stop when you feel a deep hamstring stretch, usually around mid-shin, with your back flat.\n\n4. Squeeze your glutes and drive your hips forward to stand tall. Key cue: keep the dumbbells brushing your legs the whole way down. Common mistake: squatting the weight down by bending your knees instead of hinging at the hips.",
  "Dumbbell Row":
    "1. Place one hand and the same-side knee on a bench, other foot planted, back flat and roughly parallel to the floor.\n\n2. Let the dumbbell hang straight down, then row it toward your hip with your elbow traveling back, not flaring out.\n\n3. Lower all the way until the arm is straight and you feel the lat stretch. Finish all reps before switching sides.\n\n4. Key cue: keep your shoulders square to the floor, with no twisting to steal extra range.\n\n5. Common mistake: yanking with the arm and rotating the torso. Move the weight with your back, not with body English.",
  "Dumbbell Shoulder Press":
    "1. Sit on an upright bench with the dumbbells at shoulder height, palms facing forward and elbows slightly in front of your body.\n\n2. Brace your core and keep your ribs down so you are not arching to press.\n\n3. Press up and slightly together until your arms are straight, then lower under control to ear height.\n\n4. Key cue: keep your wrists stacked directly over your elbows through the whole rep.\n\n5. Common mistake: flaring the elbows wide out to the sides, which pinches the shoulder. Keep them a touch forward.",
  "Dumbbell Shrug":
    "1. Hold a dumbbell in each hand at your sides, palms facing your thighs, standing tall.\n\n2. Brace your core and pull your shoulders straight up toward your ears.\n\n3. Pause for a second at the top and feel the traps squeeze.\n\n4. Lower slowly until your shoulders are all the way down and the traps stretch.\n\nCue: keep your chin tucked and your neck long instead of craning it forward. Common mistake: bending the elbows to help - let your arms hang straight so the traps do all the lifting.",
  "Dumbbell Side Bend":
    "1. Stand tall with feet hip-width, one dumbbell in one hand and the other hand on your hip.\n\n2. Keep your shoulders square and your chest facing straight ahead.\n\n3. Bend sideways toward the weight, letting the dumbbell slide down your thigh.\n\n4. Squeeze the opposite side to pull yourself upright, then finish all reps before switching hands.\n\nKey cue: move only side to side - no leaning forward or twisting. Common mistake: grabbing a very heavy dumbbell and cutting the range short; go moderate and feel the stretch.",
  "Elliptical":
    "1. Step on, stand tall through your hips, and keep your feet flat on the pedals instead of riding up on the toes.\n\n2. Start with light resistance and a low ramp, then build to a stride you can hold smoothly.\n\n3. Push and pull the moving handles so the effort spreads through your whole body.\n\n4. Go 20 to 40 minutes conversational, or alternate 1 minute hard with 2 minutes easy for 8 to 12 rounds.\n\nKey cue: keep pressure through the whole foot. Common mistake: leaning your bodyweight into the handles, which lets the machine carry you and drops the effort through the floor.",
  "Face Pull":
    "1. Set a rope attachment at about face height and take an overhand grip with your thumbs pointing back.\n\n2. Step back until the cable is taut and stand tall with a slight stagger in your feet.\n\n3. Pull the rope toward your forehead, spreading your hands apart and driving your elbows high and wide.\n\n4. Finish with your knuckles beside your ears, pause, then return slowly.\n\nCue: think about pulling the rope apart, not just back. Common mistake: going too heavy and leaning back - light weight with a clean end position is what makes this shoulder-friendly.",
  "Farmer's Carry":
    "1. Set a matched pair of dumbbells beside your feet and hinge at the hips to grip them.\n\n2. Stand up with a flat back, chest tall, and shoulders pulled down away from your ears.\n\n3. Brace your abs and walk 30 to 40 seconds with short, controlled steps - that is one rep.\n\n4. Hinge at the hips to set the weights down rather than dropping them.\n\nKey cue: keep your ribcage stacked over your pelvis so you do not lean back. Common mistake: shrugging and rushing - walk tall and let your grip and core do the work.",
  "Fire Hydrant":
    "1. Start on all fours with hands under your shoulders and knees under your hips.\n\n2. Brace your core so your lower back stays flat and your hips stay square to the floor.\n\n3. Keeping the knee bent at 90 degrees, lift one leg out to the side as high as you can without shifting your torso.\n\n4. Pause, lower under control, and finish all reps before switching sides. If your wrists complain, drop to your forearms. Key cue: move only at the hip. Common mistake: rolling your whole body away from the working leg to fake extra height.",
  "Flat Dumbbell Fly":
    "1. Lie on a flat bench with a dumbbell in each hand pressed over your chest, palms facing each other.\n\n2. Soften your elbows into a slight bend and lock that angle in for the whole set.\n\n3. Open your arms out in a wide arc until your hands are roughly level with your chest and you feel a stretch.\n\n4. Squeeze your chest to bring the dumbbells back together over your sternum, keeping the same elbow bend.\n\nKey cue: think about hugging a tree, not pressing. Common mistake: going heavy and turning it into a sloppy press, which loads the shoulder capsule instead of the chest.",
  "Flutter Kick":
    "1. Lie on your back with your hands tucked under your glutes and your legs straight.\n\n2. Press your low back into the floor and lift both heels about six inches.\n\n3. Alternate small, quick kicks up and down without letting your feet touch the ground.\n\n4. Count one rep each time both legs have kicked once, and stop the set when your back starts to arch.\n\nKey cue: keep the low back pinned down - if it lifts, raise your legs higher. Common mistake: kicking from the knees; drive from the hips with long legs.",
  "Frog Pump":
    "1. Lie on your back with the soles of your feet pressed together and your knees dropped out wide.\n\n2. Slide your heels toward your hips until you feel your glutes take over, and press your lower back into the floor.\n\n3. Drive your hips up by squeezing your glutes, hold the top for a second, then lower most of the way down.\n\n4. Keep the reps flowing for high reps until it genuinely burns.\n\n5. Key cue: push through the outer edges of your feet. Common mistake: letting your knees drift back together, which brings your quads and hamstrings back into the movement.",
  "Front Raise":
    "1. Stand tall with a dumbbell in each hand resting against the front of your thighs, palms facing you.\n\n2. Brace your abs, tuck your ribs down, and keep a slight bend in your elbows.\n\n3. Raise one or both arms straight out in front of you until your hands reach shoulder height.\n\n4. Lower all the way back to your thighs under control, without letting the weights swing.\n\nKey cue: stop at shoulder height, since going higher just hands the work to your traps. Common mistake: leaning back and heaving with the hips. If you have to rock, go lighter.",
  "Front Squat":
    "1. Rack the bar across your front delts, elbows high, fingertips hooked under the bar just outside your shoulders.\n\n2. Unrack, step back, and set your feet shoulder-width with toes slightly turned out.\n\n3. Brace your core and sit straight down, staying as upright as you can, until your thighs reach at least parallel.\n\n4. Drive up through your mid-foot and stand tall. Key cue: elbows up and chest proud the entire rep. Common mistake: letting the elbows drop on the way up, which rounds your upper back and dumps the bar forward off your shoulders.",
  "Glute Bridge":
    "1. Lie on your back with your knees bent and your heels about a hand's length from your glutes.\n\n2. Press your lower back gently into the floor and brace your abs before you move.\n\n3. Drive through your heels to lift your hips until your knees, hips, and shoulders form a straight line, squeezing your glutes for a full second at the top.\n\n4. Key cue: tuck your pelvis slightly so the glutes, not the lower back, finish the rep. Common mistake: pushing through your toes, which hands the work to your hamstrings and often triggers cramping.",
  "Glute-Ham Raise":
    "1. Set the foot plate so your knees sit just behind the pad, with your ankles secured under the rollers.\n\n2. Start upright with your hips fully extended and your body in a straight line from knees to head.\n\n3. Lower yourself forward as slowly as you can, resisting the whole way with your hamstrings.\n\n4. When you can no longer hold, catch yourself lightly with your hands, then push off just enough to pull back up. Key cue: keep your hips locked straight for the entire rep. Common mistake: bending at the hips to make it easier, which turns it into a back extension.",
  "Goblet Squat":
    "1. Hold one dumbbell or kettlebell vertically against your chest with your elbows tucked in underneath it.\n\n2. Stand shoulder-width with your toes slightly out, brace your core, and sit straight down between your feet.\n\n3. Go as deep as you can with a flat spine, letting your elbows travel inside your knees, then stand and squeeze your glutes.\n\n4. Key cue: the weight is a counterbalance, so let it help you stay upright and tall. Common mistake: letting the weight drift away from your chest, which rounds your upper back and cuts your depth short.",
  "Good Morning":
    "1. Set a bar across your upper traps like a squat, feet hip to shoulder-width, knees softly bent.\n\n2. Brace your core and push your hips straight back, hinging your torso toward parallel with the floor.\n\n3. Stop when you feel a strong hamstring stretch and your back is still flat.\n\n4. Drive your hips forward to stand tall and squeeze the glutes. Start with an empty bar and add weight slowly. This stays light even for strong lifters, so never load it like a deadlift. Key cue: hips travel back, not down. Common mistake: going too heavy or too deep and turning it into a rounded-back bend.",
  "Hack Squat":
    "1. Set your shoulders under the pads and place your feet mid-platform, shoulder-width, toes slightly out.\n\n2. Release the safety handles and brace your core with your whole back flat against the pad.\n\n3. Lower under control until your knees reach roughly 90 degrees, keeping both heels down.\n\n4. Press through your full foot back up without slamming the knees straight. Key cue: keep your hips glued to the pad from start to finish. Common mistake: chasing depth you do not have yet, which lets your lower back peel off the pad at the bottom.",
  "Hammer Curl":
    "1. Stand tall with a dumbbell in each hand, palms facing each other and thumbs up, like holding two hammers.\n\n2. Keep that neutral grip and curl the weight toward your shoulder, bending only at the elbow.\n\n3. Lower slowly to a fully straight arm, then repeat, alternating sides or lifting both together.\n\n4. Key cue: palms stay facing in the whole time. This grip trains the brachialis and forearm, and it is usually the friendliest curl for cranky wrists.\n\n5. Common mistake: driving the dumbbells up with a hip swing. Stay quiet from the waist down.",
  "Handstand Push-Up":
    "1. Clear the space around you and know your bail-out before you start: tuck your chin and step down to one side.\n\n2. Face away from a wall and place your hands about shoulder width apart, 6 to 12 inches from the baseboard.\n\n3. Kick up so your heels rest lightly on the wall, then squeeze your glutes and abs to hold one rigid line.\n\n4. Bend your elbows and lower until the top of your head lightly touches a folded pad, elbows tracking forward rather than flaring wide.\n\n5. Press back to straight arms without losing that stacked position.\n\nKey cue: ribs stacked over hips, never a banana arch. Common mistake: trying these before you own strict overhead presses and pike push-ups.",
  "Hanging Leg Raise":
    "1. Hang from a bar with a firm grip and your shoulders pulled down away from your ears, legs together.\n\n2. Tilt your pelvis back first so your lower back flattens, then raise your legs to at least parallel with the floor.\n\n3. Lower slowly under control and let any swing settle completely before the next rep.\n\n4. Key cue: the rep starts with the pelvis curling up, not the hip flexors flinging the legs. Bend your knees if straight legs make you swing.\n\n5. Common mistake: kipping for momentum. Slow reps with bent knees beat sloppy straight-leg swings every time.",
  "Hill Sprints":
    "1. Find a hill with a steady 5 to 10 percent grade and jog 5 to 10 minutes to warm up properly.\n\n2. Run two or three build-ups at about 70 percent effort before anything all-out.\n\n3. Sprint uphill for 10 to 20 seconds with a tall torso, driving the knees and pumping the arms.\n\n4. Walk all the way back down and rest until your breathing settles, usually 2 to 3 minutes, then repeat for 6 to 10 sprints.\n\nKey cue: run tall and let the hill set your stride length. Common mistake: skipping the warm-up or cutting rest short, which is how hamstrings get pulled.",
  "Hip Abduction Machine":
    "1. Sit tall with your back flat on the pad and the outsides of your thighs against the pads.\n\n2. Set the starting width so you feel a light stretch, then hold the handles and brace your core.\n\n3. Press your knees apart smoothly until you feel the sides of your glutes contract, hold for a beat, then return slowly.\n\n4. Key cue: leaning your torso forward slightly biases the upper glutes, while sitting upright hits more of the mid glute. Common mistake: bouncing the stack with momentum and letting the weight slam you back in.",
  "Hollow Body Hold":
    "1. Lie on your back, arms overhead, legs straight, and press your lower back into the floor.\n\n2. Lift your shoulder blades and legs a few inches off the ground so your body makes a shallow banana shape.\n\n3. Hold for 20 to 30 seconds, breathing steadily - that is one rep.\n\n4. Lower everything to the floor and rest before the next hold.\n\nKey cue: the lower back stays glued to the floor the entire time. Common mistake: going too low too soon - if your back lifts, tuck your knees or keep your arms by your sides.",
  "Incline Barbell Bench Press":
    "1. Set an adjustable bench to about 30 degrees and lie back with your eyes under the bar, feet flat on the floor.\n\n2. Grip just outside shoulder width, unrack, and lower the bar to your upper chest just below the collarbone.\n\n3. Keep your shoulder blades pinned down and back into the bench for the whole set.\n\n4. Press up and slightly back over your collarbone until your elbows are straight but not jammed.\n\nKey cue: think about pushing yourself away from the bar rather than the bar away from you. Common mistake: setting the bench too steep, which turns it into a shoulder press and beats up the front delts.",
  "Incline Dumbbell Curl":
    "1. Set a bench to about 45 to 60 degrees and sit back with your head and shoulders supported.\n\n2. Let a dumbbell hang straight down from each shoulder, palms facing forward.\n\n3. Curl the dumbbells up without letting your elbows drift forward.\n\n4. Lower slowly to a full stretch with your upper arms still behind your torso.\n\nCue: keep those upper arms hanging back - the stretch on the long head is the whole point of this variation. Common mistake: swinging the elbows forward, which turns it into a standing curl and kills the stretch.",
  "Incline Dumbbell Fly":
    "1. Set a bench to about 30 degrees, sit back with a dumbbell in each hand, and press them up over your chest.\n\n2. Turn your palms to face each other and soften your elbows into a slight, fixed bend.\n\n3. Lower the dumbbells out to the sides in a wide arc until you feel a stretch across your upper chest.\n\n4. Key cue: think about hugging a big tree on the way up and squeeze the chest at the top.\n\n5. Common mistake: going too heavy and dropping too deep, which strains the front of the shoulder. Lighter wins here.",
  "Incline Dumbbell Press":
    "1. Set the bench to about 30 degrees, sit with a dumbbell on each thigh, and kick them up as you lie back.\n\n2. Start with the dumbbells just outside your chest, palms facing forward and wrists stacked over your elbows.\n\n3. Press up and slightly in until the dumbbells are over your upper chest, stopping just short of clanging them together.\n\n4. Lower under control until you feel a stretch across the upper chest, hands about level with your shoulders.\n\nKey cue: keep your ribs down and shoulder blades tucked into the bench. Common mistake: letting the elbows drift far behind the body, which strains the front of the shoulder.",
  "Incline Dumbbell Row":
    "1. Set a bench to about 30 to 45 degrees and lie chest-down with your feet braced.\n\n2. Hold a dumbbell in each hand with your arms hanging straight down, palms facing in.\n\n3. Row both dumbbells toward your hips, driving your elbows back and squeezing your shoulder blades together.\n\n4. Lower all the way until your arms are straight and your shoulder blades spread apart.\n\nCue: keep your chest glued to the pad so your back does the pulling. Common mistake: pushing off the bench with your chest to help the weight up - if you need to, go lighter.",
  "Incline Push-Up":
    "1. Place your hands slightly wider than shoulder width on a bench, box, or sturdy countertop.\n\n2. Walk your feet back until your body forms a straight line from head to heels, hands under your chest.\n\n3. Lower your chest toward the surface with your elbows at about 45 degrees, not flared to 90.\n\n4. Press away until your arms are straight, keeping your hips in line with your shoulders throughout.\n\nKey cue: squeeze your glutes and brace your abs so the middle never sags. Common mistake: leading with the head while the hips stay high, which shortens the rep. The higher the surface, the easier the exercise.",
  "Incline Treadmill Walk":
    "1. Start around 5 percent incline at a brisk walk, usually 2.5 to 3.5 mph, and build toward 10 to 12 percent as it gets easier.\n\n2. Stand tall, let your arms swing naturally, and take a normal stride rather than a tiptoe shuffle.\n\n3. Hold an effort where you can talk but would rather not, for 20 to 30 minutes.\n\n4. For intervals, raise the incline for 2 minutes, then drop it back for 2 minutes, repeating 8 to 12 times.\n\nKey cue: stay off the handrails so your legs carry your bodyweight. Common mistake: gripping the rails and leaning back, which halves the work and loads your wrists and shoulders instead.",
  "Inverted Row":
    "1. Set a bar or suspension handles around waist height and lie underneath with an overhand grip just outside shoulder width.\n\n2. Squeeze your glutes and abs so your body forms one straight line from heels to head.\n\n3. Pull your chest to the bar with elbows tracking back, then lower under control until your arms are straight.\n\n4. Key cue: adjust difficulty by walking your feet out to make it harder, or raising the bar and bending your knees to make it easier.\n\n5. Common mistake: letting the hips sag so only the chest travels. Hold the plank and move as one unit.",
  "Jump Rope":
    "1. Size the rope so the handles reach your armpits when you stand on the middle of it.\n\n2. Keep your elbows tucked near your ribs and turn the rope with your wrists, not your arms.\n\n3. Hop just an inch or two off the floor and land softly through the balls of your feet.\n\n4. Work in intervals of 30 to 60 seconds skipping and 30 seconds rest, for 10 to 15 rounds.\n\nKey cue: quiet feet mean you are absorbing your landings. Common mistake: jumping high with stiff knees, which pounds the joints and gasses you out inside a minute.",
  "Jump Squat":
    "1. Stand with feet shoulder-width, arms ready at your sides.\n\n2. Sit into a quarter to half squat with your chest up and weight through your mid-foot.\n\n3. Explode upward, driving through both feet and reaching tall in the air.\n\n4. Land softly on your whole foot, absorb through hips and knees, and reset before the next rep. Key cue: land quietly. Common mistake: landing stiff-legged with the knees caving in, which loads joints instead of muscle. End the set as soon as your landings get sloppy.",
  "Kettlebell Swing":
    "1. Stand with the bell about a foot in front of you, feet shoulder-width, and hinge back with a flat back to hike it high between your legs. A single dumbbell held by one end works too.\n\n2. Snap your hips forward hard and let the bell float to chest height with straight, relaxed arms.\n\n3. Let it fall back into the hinge, loading the hamstrings, and swing again without pausing.\n\n4. For conditioning, do 12 to 20 swings at the top of each minute for 10 to 15 minutes, stopping the set if reps get sloppy.\n\nKey cue: the hips throw the bell, the arms just hold on. Common mistake: squatting it up and lifting with the arms, which shifts the work onto your low back.",
  "Landmine Press":
    "1. Load one end of a barbell into a landmine sleeve or wedge it into a corner, and hold the free end at shoulder height.\n\n2. Stand in a staggered stance with the bar in one hand, elbow tucked in front of your ribs.\n\n3. Press up and forward along the bar's natural arc until your arm is straight.\n\n4. Lower under control back to the front of your shoulder, finishing all reps before switching sides.\n\nKey cue: let the shoulder blade travel with the arm, since this angled path is friendlier on cranky shoulders. Common mistake: twisting the torso to muscle the bar up instead of keeping your hips square.",
  "Landmine Rotation":
    "1. Load a barbell in a landmine and hold the end with both hands at chest height, arms extended.\n\n2. Stand with feet wider than your shoulders, knees soft, abs braced.\n\n3. Rotate the bar down toward one hip, letting the opposite heel pivot up as your hips turn.\n\n4. Reverse smoothly to the other side, controlling the bar the whole way. That is one rep.\n\nKey cue: let your hips and feet turn with the bar so your low back is not doing the twisting. Common mistake: pinning the feet down and cranking through the spine.",
  "Lat Pulldown":
    "1. Set the thigh pad snug, take a grip just outside shoulder width, and sit tall with a slight backward lean.\n\n2. Start each rep by pulling your shoulder blades down, then drive your elbows toward your ribs until the bar reaches your collarbone.\n\n3. Control the bar back up and let your shoulders rise slightly at the top for a full lat stretch.\n\n4. Key cue: lead with your elbows, not your hands, and think about tucking your shoulder blades into your back pockets.\n\n5. Common mistake: leaning way back and heaving the bar down with momentum. If your torso is swinging, drop the weight.",
  "Lateral Raise":
    "1. Stand tall with a light dumbbell in each hand, arms at your sides and a slight bend in the elbows.\n\n2. Lead with your elbows and lift the weights out to the sides until they reach about shoulder height, no higher.\n\n3. Lower slowly over about two seconds and stop just short of your sides to keep tension on the delts.\n\n4. Key cue: keep your thumb a touch higher than your pinky. Turning the pinky up at the top pinches the shoulder.\n\n5. Common mistake: swinging heavy weights with the traps and lower back. Go lighter and let the side delts earn it.",
  "Lateral Step-Down":
    "1. Stand on one foot on a low box or step with the other leg hanging off the side.\n\n2. Keep your hips level and your standing knee tracking over your middle toes.\n\n3. Slowly bend the standing leg to tap the free heel to the floor, taking two to three seconds on the way down.\n\n4. Press back up through the standing foot, finish your reps, then switch sides. Key cue: tap the floor lightly, do not land on it. Common mistake: letting the standing knee cave inward, which is exactly what this drill is meant to fix.",
  "Leg Extension":
    "1. Sit tall with your back against the pad and the ankle roller resting just above your shoe laces.\n\n2. Line the machine's pivot point up with your knee joint and hold the handles.\n\n3. Straighten your knees smoothly until your legs are nearly locked, pausing for a beat at the top.\n\n4. Lower for two to three seconds without letting the stack slam down. Key cue: squeeze the quads at the top rather than yanking the weight up. Common mistake: swinging your torso to launch each rep, which takes tension straight off the quads.",
  "Leg Press":
    "1. Sit deep in the seat with your back and hips flat against the pad, feet shoulder-width and mid-height on the platform.\n\n2. Unlock the safeties, then lower the sled under control until your knees reach about 90 degrees.\n\n3. Press through your whole foot until your legs are nearly straight, stopping just short of locking out your knees.\n\n4. Key cue: keep your knees tracking in line with your toes rather than caving inward. Common mistake: going so deep that your tailbone lifts off the pad, which rounds your lower back under heavy load.",
  "Leg Press Calf Raise":
    "1. Sit in the leg press and place the balls of your feet at the bottom edge of the platform with your heels hanging off.\n\n2. Release the safeties and straighten your legs, keeping a soft bend in the knees for the whole set.\n\n3. Let your heels travel down slowly for a full calf stretch.\n\n4. Press the platform away with the balls of your feet and squeeze at the top. Key cue: the knees stay in one position, only your ankles move. Common mistake: bending and straightening the knees to shift the sled, which turns it into a quarter leg press.",
  "Low-to-High Cable Fly":
    "1. Set both pulleys to the lowest setting and take a handle in each hand, palms facing forward.\n\n2. Step forward into a split stance so there is tension on the cables before you begin.\n\n3. With a slight bend in your elbows, sweep both hands up and in until they meet in front of your collarbones.\n\n4. Squeeze the upper chest for a second, then return slowly and let your arms open until you feel a stretch.\n\nKey cue: the hands finish high and close together, like the top of a clap. Common mistake: shrugging the shoulders up, which hands the work to your traps.",
  "Lying Leg Curl":
    "1. Lie face down and set the ankle pad just above your heels, with your knees just off the end of the bench.\n\n2. Grip the handles, press your hips into the pad, and brace your core.\n\n3. Curl your heels toward your glutes as far as they will go and pause for a beat at the top.\n\n4. Lower over two to three seconds until your legs are almost straight.\n\n5. Key cue: keep your hips glued to the bench. Common mistake: lifting your hips and arching your back to move a heavier stack, which shortens the range and stresses your spine.",
  "Lying Windshield Wiper":
    "1. Lie on your back with arms out wide, palms down, and legs straight up over your hips.\n\n2. Brace your abs and press your arms into the floor to anchor your upper body.\n\n3. Lower both legs slowly to one side, stopping before your opposite shoulder lifts.\n\n4. Use your abs to pull your legs back to center, then lower to the other side. That is one rep.\n\nKey cue: control the way down - the lowering is the exercise. Common mistake: dropping the legs and bouncing; bend your knees to shorten the lever if needed.",
  "Machine Ab Crunch":
    "1. Set the seat so the pads sit against your chest and your hips line up with the pivot point.\n\n2. Grip the handles, sit tall, and brace before you move.\n\n3. Crunch by rounding your upper back and driving your ribs toward your hips.\n\n4. Return slowly until you feel a stretch through your abs, stopping before the stack touches down.\n\nKey cue: shorten the distance between your ribs and pelvis - that is the whole movement. Common mistake: pulling with the arms and hinging at the hips; lower the weight and let the abs work.",
  "Machine Chest Press":
    "1. Set the seat so the handles line up with the middle of your chest, not your collarbones.\n\n2. Sit tall with your back and shoulder blades against the pad and your feet planted.\n\n3. Press the handles forward until your arms are straight with soft elbows, then return slowly until you feel a chest stretch.\n\n4. Key cue: think about squeezing your hands toward each other as you press, even though the machine holds the path for you.\n\n5. Common mistake: letting your shoulders roll forward off the pad at the top. Keep the chest proud.",
  "Machine High Row":
    "1. Set the seat so the handles sit at or slightly above shoulder height and rest your chest on the pad.\n\n2. Take a neutral or overhand grip and let your arms extend fully overhead-forward.\n\n3. Pull the handles down and back toward your ribs, driving your elbows behind you.\n\n4. Squeeze for a beat, then return slowly to a full stretch.\n\nCue: think elbows to back pockets and keep your neck relaxed. Common mistake: shrugging the shoulders up as you pull - let your shoulder blades slide down first, then row.",
  "Machine Hip Thrust":
    "1. Sit in the machine and set the pad or belt across your hip crease, not your stomach.\n\n2. Place your feet flat and shoulder-width on the platform, shins vertical at the top of the rep.\n\n3. Press your upper back into the backrest, then drive through your heels until your torso and thighs form a straight line.\n\n4. Squeeze the glutes for a beat, then lower under control without resting the weight. Key cue: tuck your ribs down and finish with the glutes. Common mistake: overarching your lower back at the top instead of ending the rep with your hips.",
  "Machine Lateral Raise":
    "1. Adjust the seat so the machine's pivot points line up with your shoulder joints.\n\n2. Sit tall with your back on the pad and your upper arms against the arm pads, elbows slightly bent.\n\n3. Drive your elbows out and up until your upper arms are level with your shoulders.\n\n4. Pause briefly at the top, then lower slowly and resist the pads on the way down.\n\nKey cue: lead with the elbows, not the hands, so the side delts do the work. Common mistake: raising above shoulder height and shrugging, which shifts the load to your traps.",
  "Machine Preacher Curl":
    "1. Adjust the seat so your upper arms lie flat on the pad with your armpits at the top edge.\n\n2. Grip the handles palms-up and let your arms extend until you feel a light stretch.\n\n3. Curl the handles up until your biceps are fully squeezed.\n\n4. Lower under control back to a nearly straight arm position.\n\nCue: let your elbows stay pinned in one spot on the pad while your forearms do the traveling. Common mistake: sliding your body back to power through the sticking point - lighten the load and finish with your arms.",
  "Machine Shoulder Press":
    "1. Adjust the seat so the handles start at about shoulder height, not above your ears.\n\n2. Sit with your back flat against the pad, feet planted, and core braced.\n\n3. Press the handles overhead until your arms are straight with soft elbows, then lower slowly to the starting height.\n\n4. Key cue: keep even pressure through your whole hand rather than gripping with just the fingers.\n\n5. Common mistake: bouncing out of the bottom and letting the stack slam down. Control both directions of every rep.",
  "Meadows Row":
    "1. Set one end of a barbell in a landmine and stand perpendicular to it in a staggered stance, near foot forward.\n\n2. Hinge over and brace your free hand on your forward thigh or a bench, back flat.\n\n3. Take an overhand grip on the sleeve and row it up and back toward your hip.\n\n4. Lower slowly, letting your shoulder blade travel forward at the bottom.\n\nCue: pull the elbow high and behind you to load the upper back. Common mistake: twisting the torso to finish the rep - keep your shoulders level and let the arm travel.",
  "Negative Pull-Up":
    "1. Step or jump up so your chin is already over the bar with an overhand grip.\n\n2. Set your shoulder blades down and back, chest up, ribs down.\n\n3. Lower yourself as slowly as you can, aiming for 3 to 5 seconds, until your arms are straight.\n\n4. Step back up to the top and reset - do not try to pull yourself up.\n\nCue: fight the descent the whole way instead of holding at the top and then dropping. Common mistake: letting your shoulders shrug up to your ears at the bottom - keep them pulled down as you finish.",
  "Nordic Curl":
    "1. Kneel on a pad with your ankles anchored under a secure pad, a partner's hands, or a heavily loaded barbell that will not shift.\n\n2. Squeeze your glutes so your body is a straight line from knees to shoulders, hands ready in front of your chest.\n\n3. Lower yourself forward as slowly as you can, fighting gravity with your hamstrings the whole way.\n\n4. Catch yourself with your hands, then push off just enough to return to the top.\n\n5. Key cue: hips stay fully extended, glutes on. Common mistake: hinging at the hips on the way down, which turns a brutal hamstring lift into a slow bow.",
  "Overhead Dumbbell Carry":
    "1. Press two dumbbells overhead with elbows locked and your biceps beside your ears.\n\n2. Tuck your ribs down and squeeze your glutes so your back does not arch.\n\n3. Walk 20 to 30 seconds with the weights steady overhead - that is one rep.\n\n4. Lower the dumbbells to your shoulders under control before setting them down.\n\nKey cue: actively push the weights toward the ceiling for the whole walk. Common mistake: letting the ribs flare and the low back arch - start light and shorten the distance.",
  "Overhead Press":
    "1. Set the bar on your front delts, hands just outside shoulder width, elbows slightly in front of the bar.\n\n2. Squeeze your glutes and brace your abs hard so your ribs stay stacked over your hips.\n\n3. Press the bar straight up, moving your head back slightly to clear it, then shrug your shoulders up at the top.\n\n4. Key cue: finish with the bar over the middle of your feet, not out in front of your face.\n\n5. Common mistake: leaning back and arching the lower back to muscle the bar up. Brace harder and use less weight.",
  "Overhead Triceps Extension":
    "1. Sit on a bench with back support if you have one. Hold a single dumbbell with both hands cupped under the top plate, or a lighter dumbbell in one hand, and press it overhead.\n\n2. Brace your abs and keep your ribs stacked over your hips so your lower back does not arch.\n\n3. Bend your elbows to lower the weight behind your head until you feel a stretch along the back of your arms.\n\n4. Key cue: keep your elbows pointing forward and close to your head instead of letting them flare.\n\n5. Common mistake: wide elbows plus an arched back, which shifts the work off the triceps and onto your spine.",
  "Pallof Press":
    "1. Set a cable at chest height and stand side-on, holding the handle at your sternum with both hands.\n\n2. Step away until there is real tension, feet shoulder-width apart, knees soft.\n\n3. Brace your abs and press the handle straight out until your arms are almost straight, elbows soft.\n\n4. Resist the pull toward the machine, then bring the handle back to your chest under control.\n\nKey cue: your ribs and hips should not rotate an inch - only your arms move. Common mistake: using too much weight and twisting toward the stack; go lighter and stay square.",
  "Pec Deck":
    "1. Set the seat so the handles or pads sit at chest height with your feet flat on the floor.\n\n2. Sit back with your shoulder blades against the pad and your chest lifted.\n\n3. Bring the pads together in front of your chest and pause for a full second at the squeeze.\n\n4. Key cue: open only until you feel a comfortable stretch across the chest, never until your hands travel behind your body.\n\n5. Common mistake: letting the weight snap you open at the end of a hard set. Control the negative on every rep.",
  "Pendlay Row":
    "1. Set a loaded bar on the floor and stand with your mid-foot under it, feet hip-width.\n\n2. Hinge until your torso is roughly parallel to the floor and grip the bar just outside your knees, back flat.\n\n3. Row the bar explosively to your lower ribs while keeping your torso completely still.\n\n4. Return the bar all the way to the floor and re-brace before every rep.\n\nCue: lock your torso at parallel - the bar moves, you do not. Common mistake: standing up as you pull, which turns a strict row into a sloppy partial deadlift.",
  "Pike Push-Up":
    "1. Start in a push-up position, then walk your feet in and lift your hips high so your body makes an upside-down V.\n\n2. Place your hands slightly wider than your shoulders with fingers pointing forward and weight through the whole palm.\n\n3. Bend your elbows to lower the top of your head toward the floor between your hands, elbows angled back about 45 degrees.\n\n4. Key cue: press back to straight arms while keeping your hips stacked high over your hands.\n\n5. Common mistake: letting the hips drift back into a regular push-up, which turns it into chest work. Hold that V shape.",
  "Pistol Squat":
    "1. Stand on one leg with the other leg extended in front of you and arms out for balance.\n\n2. Push your hips back and lower slowly, keeping the heel of your standing foot planted.\n\n3. Descend as deep as you can control, ideally hamstring to calf, with the free leg off the floor.\n\n4. Drive through your whole foot to stand back up. Build up with box pistols or a light counterweight first. Key cue: sit back, do not fall forward. Common mistake: dropping fast and collapsing at the bottom, which slams the knee at its weakest point.",
  "Plank":
    "1. Set your forearms on the floor directly under your shoulders, elbows at about ninety degrees, feet hip width apart.\n\n2. Squeeze your glutes and tuck your ribs down so your body makes one straight line from heels to head.\n\n3. Breathe steadily and hold for time, ending the set when your hips start to drop rather than pushing to failure.\n\n4. Key cue: think about pulling your elbows toward your toes. That switches the abs on instead of letting you hang on your shoulders.\n\n5. Common mistake: hips piking up or the lower back sagging. Thirty quality seconds beats two sloppy minutes.",
  "Plank Shoulder Tap":
    "1. Start in a high plank with hands under shoulders and feet a little wider than your hips.\n\n2. Squeeze your glutes and brace your abs so your body is one straight line.\n\n3. Lift one hand and tap the opposite shoulder without letting your hips rotate.\n\n4. Replace the hand and tap with the other side. That is one rep.\n\nKey cue: push the floor away and keep your hips as still as if a cup were resting on your back. Common mistake: letting the hips swing side to side - widen your feet to make it easier.",
  "Preacher Curl":
    "1. Set the preacher bench so the top of the pad sits under your armpits and your chest rests against it.\n\n2. Take an underhand shoulder-width grip on an EZ or straight bar, arms flat on the pad.\n\n3. Curl the bar up until your forearms are just past vertical, squeezing the biceps.\n\n4. Lower slowly until your arms are almost straight.\n\nCue: keep both triceps glued to the pad for the entire set. Common mistake: dropping the weight fast at the bottom - the stretched position is where elbows get cranky, so control it.",
  "Pull-Up":
    "1. Hang from the bar with hands just outside shoulder width, palms forward, squeezing your glutes and abs so your body stays rigid.\n\n2. Pull your shoulder blades down and back first, then drive your elbows down until your chin clears the bar.\n\n3. Lower under control all the way to straight arms before starting the next rep.\n\n4. Key cue: think about pulling the bar down to you rather than pulling yourself up to it.\n\n5. Common mistake: kipping and swinging the legs to get over the bar. Use a band or the assisted machine instead so every rep is honest.",
  "Push Press":
    "1. Rack the bar on your front delts with hands just outside your shoulders and elbows slightly in front of the bar.\n\n2. Brace hard, then dip straight down two to four inches by bending your knees, keeping your torso vertical.\n\n3. Drive explosively out of the dip and let that momentum carry the bar past your face.\n\n4. Finish with your arms, locking out with the bar over the middle of your foot and your head through.\n\nKey cue: the dip is short and straight down. Common mistake: leaning back to clear your chin, which dumps the load onto your low back.",
  "Push-Up":
    "1. Set your hands slightly wider than shoulder-width, stacked under the outer edges of your chest, fingers spread.\n\n2. Squeeze your glutes and brace your abs so your body is one straight line from head to heels.\n\n3. Lower until your chest is about a fist's height from the floor, elbows angled back roughly 45 degrees.\n\n4. Key cue: press the floor away from you and finish with your shoulder blades spread wide at the top.\n\n5. Common mistake: letting the hips sag or the head poke forward. If that happens, put your hands on a bench and build up from there.",
  "Rack Pull":
    "1. Set the pins or safeties in a rack so the bar starts just below your kneecaps.\n\n2. Stand with your mid-foot under the bar, grip just outside your legs, and set a flat back with your chest up.\n\n3. Brace hard, then drive your hips forward and stand tall, finishing with the bar against your thighs.\n\n4. Lower the bar back to the pins under control and reset before the next rep.\n\nCue: pull your shoulder blades down and drag the bar into your legs the whole way. Common mistake: rounding the upper back or leaning back at the top - just stand tall.",
  "Rear Delt Fly":
    "1. Hinge forward from the hips with light dumbbells hanging under your chest, back flat and knees soft. Lying chest-down on an incline bench works too.\n\n2. Keep a slight bend in your elbows and let your arms hang straight down.\n\n3. Raise the dumbbells out to the sides in a wide arc until they are level with your shoulders.\n\n4. Key cue: think about pulling your elbows apart and back rather than lifting with your hands.\n\n5. Common mistake: shrugging and jamming the shoulder blades together, which turns it into a row. Keep the traps relaxed.",
  "Renegade Row":
    "1. Set two hex dumbbells shoulder-width apart and take a high plank gripping the handles.\n\n2. Widen your feet and brace hard so your hips stay square to the floor.\n\n3. Row one dumbbell to your ribcage, keeping the elbow close to your body.\n\n4. Lower it under control and row the other side. That is one rep.\n\nKey cue: push hard through the supporting arm so that shoulder does not collapse. Common mistake: twisting the hips to help the row - go lighter and keep your belt buckle pointed at the floor.",
  "Reverse Crunch":
    "1. Lie on your back with arms by your sides and knees bent, thighs stacked over your hips.\n\n2. Press your low back into the floor and brace your abs.\n\n3. Curl your pelvis up and in, lifting your hips an inch or two off the floor.\n\n4. Lower slowly until your thighs are back over your hips without letting your feet touch down.\n\nKey cue: roll your tailbone toward your ribs rather than kicking your legs up. Common mistake: swinging the legs for momentum - slow the tempo and use a smaller range.",
  "Reverse Curl":
    "1. Hold an EZ or straight bar with an overhand grip, hands shoulder-width, arms straight at your thighs.\n\n2. Stand tall with your elbows tucked at your sides and your core braced.\n\n3. Curl the bar up leading with the backs of your hands, until your forearms are just past vertical.\n\n4. Lower slowly to a full stretch.\n\nCue: keep your wrists straight and firm rather than letting them bend back over the bar. Common mistake: using your regular curl weight - the brachialis and forearms need a lighter load to move cleanly.",
  "Reverse Hyperextension":
    "1. Lie face down on the machine with your hips right at the edge of the pad and your legs hanging down.\n\n2. Grip the handles and hook your feet into the strap or roller.\n\n3. Brace your core, then lift your legs by squeezing your glutes until your body forms a straight line.\n\n4. Lower slowly and resist the swing at the bottom. Key cue: drive with the glutes and keep your legs long, knees straight but not locked. Common mistake: using momentum and swinging past straight, which pinches the lower back instead of working the glutes.",
  "Reverse Lunge":
    "1. Stand tall with a dumbbell in each hand, arms relaxed at your sides.\n\n2. Step one foot straight back and lower until both knees are bent about 90 degrees, front shin close to vertical.\n\n3. Push through the front heel to pull the back foot forward and return to standing.\n\n4. Alternate legs, or finish all reps on one side before switching. Key cue: keep your weight in the front heel, and let your torso tip slightly forward from the hips to load the glute. Common mistake: stepping back too short, which drives the front knee well past your toes and dumps the work onto the knee joint.",
  "Reverse Pec Deck":
    "1. Swing the handles forward and set the seat so they sit at shoulder height, then sit facing the pad with your chest against it.\n\n2. Take the handles with a neutral grip and a soft bend in your elbows.\n\n3. Sweep your arms out and back in a wide arc until they line up with your body.\n\n4. Squeeze for a second, then return slowly without letting the stack touch down.\n\nCue: keep the elbow angle fixed so the motion happens at the shoulder. Common mistake: bending the arms and rowing - that shifts the work from your rear delts to your lats.",
  "Romanian Deadlift":
    "1. Stand with the barbell at your hips, feet hip-width, knees softly bent and locked at that angle.\n\n2. Push your hips straight back and let the bar drag down your thighs, staying in contact with your legs.\n\n3. Stop when you feel a strong hamstring stretch, usually around mid-shin, then drive your hips forward to stand tall.\n\n4. Key cue: keep your lats tight so the bar stays glued to your legs and your spine stays long. Common mistake: bending the knees more as you descend, which turns it into a squat and takes the hamstrings out of it.",
  "Rowing Machine":
    "1. Strap your feet in, sit tall, and set the damper around 4 to 6 for a rowing feel rather than a grinding one.\n\n2. Drive with your legs first, then swing the hips back, then pull the handle to the bottom of your ribs.\n\n3. Reverse the order on the way out: arms, hips, then knees, and keep the chain moving in a straight line.\n\n4. Row 20 to 30 minutes at a conversational pace, or do 250 to 500 meters hard with equal easy paddling, repeating 8 to 12 times.\n\nKey cue: the legs finish before the arms start. Common mistake: yanking with the arms and rounding the low back, which turns a leg exercise into a back strain.",
  "Running":
    "1. Warm up with five easy minutes of walking or light jogging before you pick up the pace.\n\n2. Run tall with a slight lean from the ankles, shoulders relaxed, and arms swinging front to back rather than across your body.\n\n3. Land with your foot under your hips at a quick, light cadence instead of reaching far out in front.\n\n4. Key cue: if you can hold a broken conversation, you are in the easy zone that builds most of your aerobic base.\n\n5. Common mistake: adding distance too fast. Bump weekly mileage by about ten percent to keep shins, knees, and hips happy.",
  "Russian Twist":
    "1. Sit on the floor with knees bent and heels down, holding a dumbbell at your chest.\n\n2. Lean back to about 45 degrees with a long, flat spine.\n\n3. Rotate your ribcage and the weight to one side, pause, then rotate to the other. That is one rep.\n\n4. Keep your chest tall the whole time and set the weight down between sets.\n\nKey cue: turn from the ribs and shoulders, not just the arms. Common mistake: rounding the low back and swinging fast - slow down and stay tall.",
  "Scapular Pull-Up":
    "1. Hang from a bar with an overhand grip and completely straight arms.\n\n2. Without bending your elbows, pull your shoulder blades down and slightly back so your body rises an inch or two.\n\n3. Hold for a second at the top, then let your shoulders travel back up into a full hang under control.\n\n4. Keep the reps slow and controlled - this is a control drill, not a race.\n\nCue: imagine tucking your shoulder blades into your back pockets. Common mistake: bending the elbows and turning it into a tiny pull-up - the arms stay locked straight throughout.",
  "Seated Cable Row":
    "1. Sit with a soft bend in the knees, chest up, and the handle in both hands at arms length.\n\n2. Pull your shoulder blades together, then row the handle to your lower ribs with your elbows close to your sides.\n\n3. Return slowly, letting your shoulder blades spread apart at the end of the reach without letting your lower back round.\n\n4. Key cue: your torso stays still and roughly upright the whole set. Only your arms and shoulder blades move.\n\n5. Common mistake: rocking back and forth from the hips to throw the weight. If you are rowing with your whole body, go lighter.",
  "Seated Calf Raise":
    "1. Sit with the balls of your feet on the platform and the pad locked snugly over your lower thighs, not your kneecaps.\n\n2. Release the safety and let your heels drop as far as they will go for a full stretch.\n\n3. Press up through the balls of your feet as high as possible and hold for a beat.\n\n4. Lower slowly, taking two to three seconds to return to the stretch.\n\n5. Key cue: bent knees shift the work to the soleus underneath, so slow full reps beat heavy weight here. Common mistake: short bouncy reps that skip the stretch entirely.",
  "Seated Leg Curl":
    "1. Sit with your back against the pad, line your knees up with the machine's pivot, and lock the thigh pad snugly over your legs.\n\n2. Hold the handles, sit tall, and brace your core.\n\n3. Curl your heels down and under the seat as far as you can, squeezing your hamstrings for a beat.\n\n4. Return slowly until your knees are nearly straight and you feel the stretch.\n\n5. Key cue: keep your toes pulled up toward your shins. Common mistake: sliding your hips forward off the backrest to help, which cuts out the stretch that makes this exercise work.",
  "Side Plank":
    "1. Lie on your side with your elbow directly under your shoulder and your feet stacked or staggered.\n\n2. Press your forearm down and lift your hips so your body forms a straight line from ear to ankle.\n\n3. Hold for 20 to 30 seconds - that is one rep - then repeat on the other side.\n\nKey cue: push your bottom hip toward the ceiling instead of letting it sag. Common mistake: rolling your chest toward the floor - stack your shoulders and hips and look straight ahead.",
  "Side-Lying Leg Raise":
    "1. Lie on your side with your body in a straight line, propped up on your bottom forearm.\n\n2. Cross your top leg over and plant that foot on the floor in front of your bottom knee.\n\n3. Keeping the bottom leg straight and the toes pointing forward, lift it toward the ceiling using your inner thigh.\n\n4. Pause at the top, then lower slowly without resting the leg on the floor.\n\n5. Key cue: stack your hips so the top one does not roll backward. Common mistake: rolling back to make the raise easier, which hands the work to your hip flexors.",
  "Single-Arm Cable Pulldown":
    "1. Set a cable to the highest pulley with a single handle, then kneel or sit facing the machine.\n\n2. Grip the handle with one hand, arm straight overhead, and let that shoulder blade rise at the top.\n\n3. Pull your elbow down toward your hip, finishing with the handle beside your ribs.\n\n4. Control the way back up and let the lat stretch fully before the next rep.\n\nCue: keep your torso square and resist the pull trying to twist you. Common mistake: leaning hard away from the machine, which turns it into a body swing instead of a lat contraction.",
  "Single-Arm Cable Row":
    "1. Set a cable to about waist height with a single handle and face the stack in a split stance.\n\n2. Grip the handle, brace your core, and let your arm extend fully so the shoulder blade travels forward.\n\n3. Pull the handle to your ribs, driving your elbow past your torso and squeezing the shoulder blade back.\n\n4. Return under control to a full stretch.\n\nCue: keep your hips and shoulders square as you pull. Common mistake: rotating the torso for extra reach - it feels strong but takes tension off the lat.",
  "Single-Leg Calf Raise":
    "1. Stand on the ball of one foot on a step or weight plate with the heel free to drop below your toes.\n\n2. Hold a wall or rail for balance and hook the free foot behind your standing ankle.\n\n3. Lower your heel slowly until you feel a full stretch through the calf.\n\n4. Press up as high as you can onto the ball of your foot and pause for a beat before the next rep. Key cue: pause at the top and the bottom. Common mistake: bouncing out of the stretch, which lets the tendon do the work instead of the calf.",
  "Single-Leg Hip Thrust":
    "1. Set your upper back on a bench with both feet on the floor, then extend one leg straight out or tuck that knee toward your chest.\n\n2. Plant the working foot flat under your knee, brace your core, and level your hips.\n\n3. Drive through the working heel until your torso is parallel to the floor, squeezing that glute hard for a beat.\n\n4. Lower with control, stopping just before your hips touch down.\n\n5. Key cue: keep both hip bones at the same height all set. Common mistake: arching your lower back to gain height instead of finishing with the glute.",
  "Single-Leg Romanian Deadlift":
    "1. Stand on one leg with a soft knee, holding a light weight in the opposite hand if you want load.\n\n2. Hinge at the hip and let the free leg extend straight behind you as your torso lowers toward parallel.\n\n3. Stop when your hamstring is stretched and your hips are still square, then squeeze the glute to stand back up.\n\n4. Key cue: picture your hip bones as headlights that must keep pointing straight at the floor. Common mistake: opening the back hip out to the side, which turns the hinge into a twist and steals the hamstring work.",
  "Single-Leg Squat to Bench":
    "1. Stand just in front of a bench facing away from it, one foot planted and the other leg extended out in front of you.\n\n2. Reach your arms forward as a counterbalance, push your hips back, and lower under control until you tap the bench.\n\n3. Keep your weight in the middle of your standing foot with the knee tracking over your toes.\n\n4. Stand back up without rocking, driving through your whole foot.\n\n5. Key cue: tap the bench, do not sit down on it. Common mistake: collapsing onto the bench, which removes the control that builds real single-leg strength.",
  "Skull Crusher":
    "1. Lie on a bench holding an EZ bar or dumbbells with a shoulder-width grip, arms straight over your chest.\n\n2. Tip your arms back slightly so they angle toward your head. This keeps tension on the triceps at the top.\n\n3. Bend only at the elbows and lower the weight to just above your forehead or slightly behind your head.\n\n4. Key cue: keep your upper arms still and let the elbows do all of the work.\n\n5. Common mistake: letting the elbows flare wide and turning it into a press. Slow down and lighten the load.",
  "Sled Push":
    "1. Load the sled so you can keep it moving at a strong, steady walk, never a stall.\n\n2. Set your hands on the uprights with arms extended and your body angled forward in one line from head to heels.\n\n3. Drive with short, powerful steps, pushing through the whole foot and keeping the sled in constant motion.\n\n4. Push 20 to 30 yards per trip, rest 60 to 90 seconds, and repeat for 8 to 12 trips.\n\nKey cue: hold a long, low body angle with your ribs braced down. Common mistake: piling on plates until you are grinding, which turns conditioning work into a low back strain.",
  "Spider Curl":
    "1. Set an incline bench to about 45 degrees and lie chest-down with your feet planted.\n\n2. Let your arms hang straight down from your shoulders, a dumbbell in each hand, palms forward.\n\n3. Curl the weights toward your shoulders without letting your upper arms swing.\n\n4. Lower slowly until your arms are completely straight.\n\nCue: keep your chest on the pad and your upper arms perpendicular to the floor. Common mistake: yanking the weight up with a shoulder shrug - go lighter and work through the full range.",
  "Squeeze Push-Up":
    "1. Set up in a push-up position with your hands close together under your chest, thumbs almost touching.\n\n2. Actively press your hands toward each other, as if squeezing the floor between them, and hold that tension.\n\n3. Brace your abs and glutes so your body stays one straight line, then lower your chest toward your hands.\n\n4. Key cue: keep squeezing inward the entire set. That constant tension is what lights up the chest.\n\n5. Common mistake: letting the elbows flare wide. Keep them tracking close to your ribs as you lower.",
  "Stability Ball Hamstring Curl":
    "1. Lie on your back with your heels on top of a stability ball and arms flat at your sides.\n\n2. Lift your hips so your body forms a straight line from shoulders to heels.\n\n3. Keeping the hips high, bend your knees and roll the ball in toward your glutes.\n\n4. Pause, then slowly straighten your legs back out without letting your hips drop. Key cue: hips stay lifted from the first rep to the last. Common mistake: letting the hips sag as you extend, which kills the tension on your hamstrings.",
  "Stair Climber":
    "1. Start the machine slow and step on with a tall chest and your hips stacked under your shoulders.\n\n2. Place your whole foot on each step and press through the heel to stand up onto it.\n\n3. Rest your hands lightly on the rails for balance only, never for support.\n\n4. Climb 15 to 25 minutes steady, or alternate 2 minutes fast with 2 minutes easy for 6 to 8 rounds.\n\nKey cue: stay upright and let the glutes do the pushing. Common mistake: hanging off the handrails with your hips sagging back, which unloads the legs and nags the low back.",
  "Stairs":
    "1. Warm up for two or three easy minutes before pushing the pace, whether on a stair machine or a real stairwell.\n\n2. Stand tall and place your whole foot on each step, driving through the heel and glute to stand up.\n\n3. Settle into a rhythm you can hold for the full interval, using the rails for balance only.\n\n4. Key cue: lean slightly forward from the hips and push the step away to load the glutes instead of the knees. If your knees complain, shorten the step height and slow the pace.\n\n5. Common mistake: hanging on the handrails so your arms carry your weight, which drops the real effort far below what the display claims.",
  "Standing Banded Abduction":
    "1. Loop a band around both ankles and stand tall beside a wall or rack for balance.\n\n2. Shift your weight onto one leg with a soft knee and brace your core.\n\n3. Keeping the working leg straight, lift it out to the side until you feel the glute on that hip switch on.\n\n4. Return slowly against the band's pull, finish your reps, then switch sides. Key cue: stand tall and lead with your heel. Common mistake: leaning your torso away from the working leg to swing it higher than your hip can actually take it.",
  "Standing Cable Abduction":
    "1. Cuff the ankle furthest from the machine and stand side-on to a low pulley, holding the frame.\n\n2. Stand tall with your ribs stacked over your hips and your weight on the inside leg.\n\n3. Sweep the working leg out to the side, leading with your heel, until you feel the side of your glute working.\n\n4. Bring it back slowly and let it cross just past the standing leg for a stretch.\n\n5. Key cue: keep your torso still and your toes pointing forward. Common mistake: leaning away from the machine so the leg swings higher, which is your obliques cheating, not your glutes.",
  "Standing Cable Leg Curl":
    "1. Set the cable to its lowest setting and fasten an ankle strap around one ankle.\n\n2. Face the machine and hold on for support, standing tall with a soft knee on your standing leg.\n\n3. Keeping your thighs level with each other, curl your heel toward your glute.\n\n4. Squeeze the hamstring at the top, then lower slowly to a full stretch and repeat before switching sides. Key cue: the working knee stays underneath your hip. Common mistake: swinging the whole thigh backward to help the weight up.",
  "Standing Calf Raise":
    "1. Stand with the balls of your feet on a step or plate, heels hanging free, holding something for balance.\n\n2. Let your heels sink below the step until you feel a deep stretch through your calves.\n\n3. Press up onto your big toes as high as you can and hold the top squeeze for a full second.\n\n4. Lower over two to three seconds back into the stretch.\n\n5. Key cue: keep your knees straight so the load stays on the big calf muscle. Common mistake: bouncing fast reps off the bottom, which uses the Achilles tendon instead of the muscle.",
  "Stationary Bike":
    "1. Set the saddle so your knee keeps a slight bend at the bottom of the pedal stroke, and hold the bars with relaxed arms.\n\n2. Spin easy for 3 to 5 minutes before you touch the resistance.\n\n3. For steady cardio, ride 20 to 40 minutes at a pace where you can still speak in short sentences.\n\n4. For intervals, add resistance and push 30 to 60 seconds hard, then spin easy for 60 to 90 seconds, repeating 8 to 12 times.\n\nKey cue: drive from the legs with a quiet, stable upper body. Common mistake: dropping the resistance to nothing and spinning wildly, which feels breathless but does very little real work.",
  "Step-Up":
    "1. Set a box or bench at knee height or lower, so your thigh is about parallel or a little higher when your foot is on it.\n\n2. Hold dumbbells at your sides, place one whole foot on the box, and lean your torso forward slightly.\n\n3. Drive through that heel to stand up, keeping the trailing leg passive rather than pushing off the floor.\n\n4. Lower under control and tap the floor lightly before the next rep.\n\n5. Key cue: stand up with the top leg only, no bounce off the bottom leg. Common mistake: pushing off the back toe, which lets the working leg cheat and kills the glute work.",
  "Straight-Arm Pulldown":
    "1. Stand facing a high pulley with a straight bar or rope, feet hip-width and hips hinged slightly.\n\n2. Take the attachment with arms nearly straight, a soft bend in the elbows, hands about eye height.\n\n3. Keeping that elbow angle fixed, sweep the bar down in an arc until it reaches your thighs.\n\n4. Return slowly overhead until you feel your lats stretch.\n\nCue: think of one long arc from the shoulder, not a triceps pushdown. Common mistake: bending and straightening the elbows, which hands the work to your triceps instead of your lats.",
  "Suitcase Carry":
    "1. Stand beside one dumbbell, hinge at the hips with a flat back, and grip it at your side.\n\n2. Brace your abs, pull that shoulder back and down, and stand up without leaning.\n\n3. Walk 30 to 40 seconds in a straight line with slow, deliberate steps - that is one rep.\n\n4. Hinge to set the weight down, switch hands, and repeat on the other side.\n\nKey cue: stay perfectly upright, as if walking between two panes of glass. Common mistake: side-bending away from the weight - lower the load until you can stay level.",
  "Sumo Deadlift":
    "1. Take a wide stance with toes turned out about 45 degrees and shins close to the bar.\n\n2. Hinge and drop your hips, gripping the bar inside your knees with a flat back and tall chest.\n\n3. Pull the slack out of the bar, brace hard, then push the floor apart and stand up, keeping the bar against your legs.\n\n4. Lock out hips and knees together, then hinge the bar back down. Key cue: spread the floor with your feet to open the hips. Common mistake: letting your hips shoot up first, which turns it into a stiff-legged pull on your lower back.",
  "Swimming":
    "1. Pick a stroke you can repeat comfortably, usually freestyle or breaststroke, swim only in supervised water, and warm up with 5 minutes of easy laps.\n\n2. Breathe on a rhythm instead of holding your breath, exhaling steadily into the water.\n\n3. Keep your hips high and your body long rather than kicking harder to stay afloat.\n\n4. Swim 20 to 30 minutes continuous, or alternate one hard length with one easy length for 12 to 20 rounds.\n\nKey cue: reach long on every stroke and let the glide do some of the work. Common mistake: sprinting the first few lengths, then spending the session hanging on the wall.",
  "T-Bar Row":
    "1. Load one end of a barbell in a landmine or corner and straddle it with a V-handle hooked under the bar.\n\n2. Hinge to about 45 degrees with a flat back and soft knees, then lift the bar to arms' length.\n\n3. Row the handle to your lower chest by driving your elbows back and down.\n\n4. Lower under control until your arms are straight and your lats stretch.\n\nCue: keep your chest proud and your spine neutral for the whole set. Common mistake: rounding the upper back and jerking with the hips - pick a weight you can move with a still torso.",
  "Toes to Bar":
    "1. Hang from a pull-up bar with an overhand grip, hands just outside shoulder width.\n\n2. Pull your shoulder blades down and back so you are not hanging loose.\n\n3. Brace your abs and lift straight legs all the way up until your toes touch the bar.\n\n4. Lower with control and stop any swing before starting the next rep.\n\nKey cue: pull the bar slightly toward you with your lats to keep your body stable. Common mistake: kipping wildly and losing tension - build up with strict hanging knee raises first.",
  "Trap Bar Deadlift":
    "1. Stand in the middle of the trap bar with feet hip-width and take a firm grip on the handles.\n\n2. Drop your hips, lift your chest, keep your arms straight, and pull the slack out of the bar.\n\n3. Brace your core and stand up by pushing your feet through the floor.\n\n4. Lock out tall, then hinge your hips back and lower the bar under control. Key cue: push the floor away instead of pulling with your arms. Common mistake: rounding the upper back before the bar moves. Set your chest first, then pull.",
  "Triceps Kickback":
    "1. Hinge forward at the hips with a flat back, one hand supported on a bench and a dumbbell in the other.\n\n2. Pin your upper arm against your side so it is parallel to the floor, elbow bent to 90 degrees.\n\n3. Straighten your elbow until the whole arm is in line with your torso, turning your pinky slightly up.\n\n4. Squeeze the triceps for a beat, then lower back to 90 degrees under control.\n\nKey cue: the only thing that moves is your forearm. Common mistake: swinging the upper arm to fling the weight back, which is why kickbacks need light weight and strict form.",
  "Triceps Pushdown":
    "1. Set the cable at the top, grab the bar or rope with a shoulder-width grip, and take a half step back.\n\n2. Pin your elbows to your sides and lean forward just slightly from the hips.\n\n3. Straighten your arms fully, squeezing the triceps for a beat at the bottom, then let the weight rise to about 90 degrees.\n\n4. Key cue: only your forearms move. Your upper arms stay glued in place for the entire set.\n\n5. Common mistake: using body weight to shove the bar down. If you are bouncing at the hips, drop the weight.",
  "V-Up":
    "1. Lie flat with arms extended overhead and legs straight, low back pressed into the floor.\n\n2. Brace your abs and lift your arms and legs at the same time, folding at the hips.\n\n3. Reach toward your toes at the top so your torso and legs form a V.\n\n4. Lower everything under control without letting your heels or hands slam the floor.\n\nKey cue: lead with your ribs curling toward your hips, not with your chin. Common mistake: bouncing off the floor - do tuck-ups until you can control the full version.",
  "Walking Lunge":
    "1. Hold a dumbbell in each hand at your sides and stand tall with your ribs down and shoulders back.\n\n2. Step forward far enough that both knees bend to about 90 degrees, front shin close to vertical and back knee hovering just off the floor.\n\n3. Push through the front heel to bring the back leg through into the next step, staying tall the whole way.\n\n4. Key cue: keep your torso upright and your front knee stacked over the middle of your foot. Common mistake: taking short, choppy steps, which shifts the work onto your knees instead of your glutes.",
  "Weighted Pull-Up":
    "1. Load a dip belt with a plate or pinch a dumbbell between your feet, then take an overhand grip just outside shoulder width.\n\n2. Hang with arms straight and shoulder blades set down, then pull until your chin clears the bar.\n\n3. Lower slowly to a full hang and let the weight settle before the next rep.\n\n4. Only add load once you can do 8 clean bodyweight reps.\n\nCue: hold a slight hollow-body position with legs still and toes pointed. Common mistake: adding weight too soon and cutting the bottom short - full range beats extra plates.",
  "Weighted Sit-Up":
    "1. Lie on your back with knees bent and feet flat or anchored, holding a dumbbell or plate against your chest.\n\n2. Curl up one vertebra at a time with your chin slightly tucked until your torso is upright.\n\n3. Lower with the same control, resisting the whole way down until your shoulder blades touch the floor.\n\n4. Key cue: peel your spine off the floor segment by segment instead of hinging up in one rigid board.\n\n5. Common mistake: jerking the weight for momentum or pulling on your neck. Keep the load at your chest and go lighter if the reps turn fast and choppy.",
};
